// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, address target, uint256 value) public {
        vm.assume(actor != c.owner());
        vm.deal(address(c), 100 ether);
        vm.assume(value <= address(c).balance);
        vm.prank(actor);
        bool ok = true;
        try c.sendMoney(target, value) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "sendMoney should revert for non-owner");
    }
}
